        if (choice == 1) {
            int y;
            printf("Enter year (e.g. 2024): ");
            if (scanf("%d", &y) == 1) {
                if (is_leap_year(y)) {
                    printf("%d is a LEAP YEAR (366 days, Feb has 29 days).\n", y);
                } else {
                    printf("%d is a COMMON YEAR (365 days, Feb has 28 days).\n", y);
                }
            }
        } else if (choice == 2) {
