            int y;
            printf("Enter year: ");
            if (scanf("%d", &y) == 1) {
                printf("February %d has %d days.\n", y, is_leap_year(y) ? 29 : 28);
            }
        }
        clear_input();
    } while (choice != 0);

    return 0;
}

